statement: -- Conceder permissões de uso no schema public
GRANT USAGE ON SCHEMA public TO anon, authenticated;

-- Conceder todas as permissões em todas as tabelas para usuários anônimos e autenticados
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated;

-- Conceder todas as permissões em todas as sequências (se houver)
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;

-- Garantir que a RLS (Segurança em Nível de Linha) está desativada para não bloquear os acessos
ALTER TABLE public.events DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.users DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_fornecedores DISABLE ROW LEVEL SECURITY;
ALTER TABLE public.event_registros DISABLE ROW LEVEL SECURITY;
